from abc import ABCMeta, abstractmethod


class CmdBuilder(object):
    """Base class responsible for tshark command preparation. """

    __metaclass__ = ABCMeta

    def __init__(self, tshark_path, display_filter, preferences=None, log_dir=None):
        self._log_dir = log_dir
        self._tshark = tshark_path
        self._display_filter = display_filter
        self._preferences = '-o {} '.format(' -o '.join(preferences.split())) if preferences else ''

    @abstractmethod
    def build(self):
        """ Abstract method to prepare command for tshark. """


class CapturingCmdBuilder(CmdBuilder):
    """ Class prepares tshark command, which allows to save packets into pcap files. """

    CMD = "{bin}/tshark -i {eth} -f \'{cfil}\' -s {snap} -w \'{log}\' {packets_option}{duration_option}{split_option}{override_preferences}" \
          "> /dev/null 2> {log_dir}/{classname}_tshark_error_log & echo $!"

    def __init__(self, tshark_path, interface, capture_filter, pcap_file, snap, split, display_filter, preferences, log_dir, duration, packets):
        super(CapturingCmdBuilder, self).__init__(tshark_path, display_filter, preferences, log_dir)
        self._capture_interface = interface.split()
        self._capture_filter = capture_filter
        self._pcap = pcap_file
        self._snap = snap
        self._split = split
        self._duration = '-a duration:{} '.format(duration) if duration else ''
        self._packets = '-c {} '.format(packets) if packets else ''

    def build(self):
        """ Builds tshark command. """
        capture_interfaces = ' -i '.join(self._capture_interface)
        return CapturingCmdBuilder.CMD.format(bin=self._tshark, eth=capture_interfaces,
                                              cfil=self._capture_filter, snap=self._snap, log=self._pcap,
                                              duration_option=self._duration, packets_option=self._packets,
                                              split_option=self._set_file_max_size(),
                                              override_preferences=self._preferences, log_dir=self._log_dir, classname='SavingPackets')

    def _set_file_max_size(self):
        return '' if not self._split else '-b filesize:{} '.format(self._split)


class CountingCmdBuilder(CmdBuilder):
    """ Class prepares tshark command, which allows to store packets as txt files."""

    CMD = "{bin}/tshark -i {eth} {override_preferences}{filter_option} \'{pfil}\' -l > "\
          "{log} 2>{log_dir}/{classname}_tshark_error_log & echo $!"

    def __init__(self, tshark_path, interface, packet_filter, log_file, display_filter, preferences, log_dir):
        super(CountingCmdBuilder, self).__init__(tshark_path, display_filter, preferences, log_dir)
        self._capture_interface = interface.split()
        self._packet_filter = packet_filter
        self._log_file = log_file

    def build(self):
        """ Builds tshark command. """
        capture_interfaces = ' -i '.join(self._capture_interface)
        return CountingCmdBuilder.CMD.format(bin=self._tshark, eth=capture_interfaces,
                                             override_preferences=self._preferences,
                                             filter_option=self._display_filter,
                                             pfil=self._packet_filter,
                                             log=self._log_file, log_dir=self._log_dir, classname='CountingPackets')


class ReadingCmdBuilder(CmdBuilder):
    """ Class prepares tshark command, which allows to read pcap files and return packet content in text or xml form."""

    CMD = "{bin}/tshark -r \'{pcap}\' {override_preferences}{filter_option} \'{pfil}\' -T {type}{decode}{fields}"

    FORMS = {'lines': 'text', 'text': 'text -V', 'pdml': 'pdml', 'json': 'json', 'fields': 'fields'}

    def __init__(self, tshark_path, packet_filter, pcap_path, output_type, display_filter, preferences, decode_as, fields):
        super(ReadingCmdBuilder, self).__init__(tshark_path, display_filter, preferences)
        self._pcap = pcap_path
        self._packet_filter = packet_filter
        self._format = output_type
        self._decode = decode_as
        self._fields = fields

    def build(self):
        """ Builds tshark command. """
        decode_as = ' -d {}'.format(self._decode) if self._decode else ''
        fields_option = ' -e {}'.format(' -e '.join(self._fields)) if self._fields else ''
        return ReadingCmdBuilder.CMD.format(bin=self._tshark, pcap=self._pcap,
                                            override_preferences=self._preferences,
                                            filter_option=self._display_filter,
                                            pfil=self._packet_filter,
                                            type=ReadingCmdBuilder.FORMS[self._format], decode=decode_as, fields=fields_option)
